inline std::wstring env(const wchar_t* name){wchar_t v[32768]{};const auto n=GetEnvironmentVariableW(name,v,32768);return n&&n<32768?std::wstring(v,n):std::wstring{};}
inline bool same(const std::wstring& a,const std::wstring& b){return !a.empty()&&!b.empty()&&_wcsicmp(a.c_str(),b.c_str())==0;}
inline bool plainPath(const std::wstring& path,bool directory){
 if(path.size()<4||path[1]!=L':'||path[2]!=L'\\')return false;
 for(size_t i=3;i<=path.size();++i){if(i<path.size()&&path[i]!=L'\\')continue;const auto part=path.substr(0,i);const DWORD a=GetFileAttributesW(part.c_str());if(a==INVALID_FILE_ATTRIBUTES||(a&FILE_ATTRIBUTE_REPARSE_POINT))return false;if(i<path.size()&&!(a&FILE_ATTRIBUTE_DIRECTORY))return false;if(i==path.size()&&bool(a&FILE_ATTRIBUTE_DIRECTORY)!=directory)return false;}return true;
}
struct BoundContext {std::wstring root,exe,dll;};
inline BoundContext checkedContext(){
 BoundContext c{env(L"YMCC_PRIVATE_RUN_ROOT"),env(L"YMCC_PRIVATE_EXE"),env(L"YMCC_PRIVATE_MANAGED_DLL")};
 wchar_t cwd[32768]{},exe[32768]{};const auto nc=GetCurrentDirectoryW(32768,cwd),ne=GetModuleFileNameW(nullptr,exe,32768);
 if(!nc||nc>=32768||!ne||ne>=32768||!same(c.root,cwd)||!same(c.exe,exe)||!same(c.root,env(L"YEMAN_POWER_CONTROL_DIR"))||!plainPath(c.root,true)||!plainPath(c.exe,false)||!plainPath(c.dll,false))ExitProcess(ERROR_ACCESS_DENIED);
 return c;
}
// Declaration precedes main.inert.cpp, hence precedes POWER_CONTROL_DIR initialization in this TU.
static const BoundContext bound=checkedContext();
inline void requireContext(){const auto c=checkedContext();if(!same(c.root,bound.root)||!same(c.exe,bound.exe)||!same(c.dll,bound.dll))ExitProcess(ERROR_ACCESS_DENIED);}
inline std::vector<wchar_t> childEnvironment(DWORD parent,const std::wstring& pipe,const std::wstring& nonce){
 std::vector<std::wstring> vars={L"SystemRoot=C:\\Windows",L"DOTNET_ROOT=C:\\Program Files\\dotnet",L"DOTNET_MULTILEVEL_LOOKUP=0",L"YEMAN_POWER_CONTROL_DIR="+bound.root,L"YMCC_PRIVATE_RUN_ROOT="+bound.root,L"YMCC_PRIVATE_EXE="+bound.exe,L"YMCC_PRIVATE_MANAGED_DLL="+bound.dll,L"YMCC_PRIVATE_PARENT_PID="+std::to_wstring(parent),L"YMCC_PRIVATE_PIPE="+pipe,L"YMCC_PRIVATE_NONCE="+nonce};
 std::sort(vars.begin(),vars.end(),[](const auto& a,const auto& b){return _wcsicmp(a.c_str(),b.c_str())<0;});
 std::vector<wchar_t> block;for(const auto& v:vars){block.insert(block.end(),v.begin(),v.end());block.push_back(0);}block.push_back(0);return block;
}
}

