using System.IO;using System.IO.Pipes;using System.Runtime.InteropServices;using Microsoft.Win32.SafeHandles;
internal static class PrivateRuntimeGuard {
 private static string Env(string name)=>Environment.GetEnvironmentVariable(name)??"";
 private static bool Same(string a,string b)=>a.Length>0&&b.Length>0&&string.Equals(Path.GetFullPath(a),Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);
 private static bool Plain(string p){if(!Path.IsPathFullyQualified(p))return false;for(var at=Path.GetFullPath(p);!string.IsNullOrEmpty(at);at=Path.GetDirectoryName(at)??""){if((File.GetAttributes(at)&FileAttributes.ReparsePoint)!=0)return false;}return true;}
 internal static void ValidateLaunch(string pipe,int parent,string receipt,string nonce){
  var root=Env("YMCC_PRIVATE_RUN_ROOT");if(!Same(root,Environment.CurrentDirectory)||!Same(root,Env("YEMAN_POWER_CONTROL_DIR"))||!Plain(root)||!Same(typeof(PrivateRuntimeGuard).Assembly.Location,Env("YMCC_PRIVATE_MANAGED_DLL"))||!Plain(typeof(PrivateRuntimeGuard).Assembly.Location)||!Same(Path.GetDirectoryName(receipt)??"",root)||!Plain(Path.GetDirectoryName(receipt)!)||!int.TryParse(Env("YMCC_PRIVATE_PARENT_PID"),out var expected)||parent!=expected||pipe!=Env("YMCC_PRIVATE_PIPE")||nonce!=Env("YMCC_PRIVATE_NONCE"))throw new InvalidDataException("private-launch-binding");
 }
 internal static void ValidateServer(NamedPipeClientStream pipe,int expectedParent){if(!GetNamedPipeServerProcessId(pipe.SafePipeHandle,out var actual)||actual!=(uint)expectedParent)throw new IOException("private-pipe-server-not-native-parent");}
 [DllImport("kernel32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]private static extern bool GetNamedPipeServerProcessId(SafePipeHandle pipe,out uint pid);
}
